    {
      "symbol": "A02",
      "target_weight": 0.145,
      "rationale": "Narrowest 5d interval among equities (3.6%) and low 10% vol; broad US core. Raised ~2.4pp from current (funded from cash), +4.6pp vs baseline — within the 15pp increase allowance. Lowest-uncertainty place to deploy excess cash.",
      "confidence": 0.55
    },
    {
      "symbol": "A11",
      "target_weight": 0.0499,
      "rationale": "Tech-growth ETF with a wide 6.2% interval and 19.7% vol; held slightly below baseline (5.7%). No edge to add given uninformative median.",
      "confidence": 0.5
    },
    {
      "symbol": "A10",
      "target_weight": 0.0863,
      "rationale": "Second us_broad ETF, moderate 5.5% interval, 15% vol, positive 5d/20d recent returns; kept above baseline (6.5%) as part of the low-uncertainty core. us_broad group total 23.1% < 30% cap.",
      "confidence": 0.5
    },
    {
      "symbol": "A06",
      "target_weight": 0.0956,
      "rationale": "Intl developed ETF: narrow 4.1% interval, low 10.6% vol; kept above baseline (8.7%) for diversification outside the US-heavy book.",
      "confidence": 0.55
    },
    {
      "symbol": "A12",
      "target_weight": 0.0,
      "rationale": "Emerging markets: 7.9% interval (among the widest), 20.7% vol, and -4.9% over 20d. Staying at zero, 4.5pp below baseline — high forecast uncertainty with no compensating signal.",
      "confidence": 0.6
    },
    {
      "symbol": "A03",
      "target_weight": 0.0495,
      "rationale": "Energy ETF: strong 20d run (+11.3%) but 6.8% interval and 21.6% vol; medians have no skill so no reason to chase or to fade. Held near baseline (5.2%).",
      "confidence": 0.5
    },
    {
      "symbol": "A04",
      "target_weight": 0.0593,
      "rationale": "Health ETF, moderate 5.1% interval, 18% vol; trimmed ~1pp vs baseline (7.0%) in favor of narrower-interval assets.",
      "confidence": 0.5
    },
    {
      "symbol": "A08",
      "target_weight": 0.119,
      "rationale": "Financials ETF: narrow 4.5% interval, lowest vol of the equity book (11.4%), +5.1% over 20d. Largest overweight vs baseline (7.9%) — justified by low forecast uncertainty. Financials group with A15 = 18.0% < 30% cap.",
      "confidence": 0.55
    },
    {
      "symbol": "A09",
      "target_weight": 0.14,
      "rationale": "Bonds: narrowest 80% interval of all 15 assets (3.9% at 5d) — the most predictable asset — and defensive ballast. Raised ~2.2pp from current, +4.8pp vs baseline, funded from cash.",
      "confidence": 0.55
    },
    {
      "symbol": "A05",
      "target_weight": 0.0194,
      "rationale": "Gold: wide 7.3% interval, 17.3% vol, -1.9% over 20d; kept near zero, 2.9pp below baseline. Not a compelling hedge at this uncertainty level.",
      "confidence": 0.55
    },
    {
      "symbol": "A01",
      "target_weight": 0.0,
      "rationale": "Tech stock with the widest interval in the universe (11.1%), 30.6% vol, -5.7% over 20d and -1.2% on the last day. Staying at zero, 3.2pp below baseline.",
      "confidence": 0.6
    },
    {
      "symbol": "A15",
      "target_weight": 0.0607,
      "rationale": "Financials stock: lowest vol among single stocks (12.9%) and moderate 6.3% interval; kept essentially at baseline (5.7%). Pairs with A08 within the 30% group cap.",
      "confidence": 0.5
    },
    {
      "symbol": "A13",
      "target_weight": 0.0303,
      "rationale": "Energy stock: +11.8% over 20d but 8.1% interval and 20.9% vol; positive median is not a signal. Kept small, 1.4pp below baseline.",
      "confidence": 0.5
    },
    {
      "symbol": "A07",
      "target_weight": 0.0,
      "rationale": "Health stock: 9.3% interval, 29% vol. Despite +11.3% over 20d, the forecast uncertainty is too wide to justify a position; staying at zero, 3.8pp below baseline.",
      "confidence": 0.6
    },
    {
      "symbol": "A14",
